    private Context? _gpuContext;
    private Accelerator? _gpuAccel;
    private Action<Index1D, ArrayView<RawPixel>, GpuParams>? _gpuKernel;
    private bool _gpuInitFailed;
    public string LastGpuError { get; private set; } = string.Empty;

    private bool TryInitGpu()
    {
        if (_gpuKernel != null) return true;
        if (_gpuInitFailed) return false;
        try
        {
            _gpuContext = Context.Create(b => b.Default());
            _gpuAccel   = _gpuContext.GetPreferredDevice(preferCPU: false).CreateAccelerator(_gpuContext);
            _gpuKernel  = _gpuAccel.LoadAutoGroupedStreamKernel<Index1D, ArrayView<RawPixel>, GpuParams>(Kernel);
            return true;
        }
        catch (Exception ex)
        {
            LastGpuError = ex.Message;
            _gpuInitFailed = true;
            return false;
        }
    }

    private bool TryRenderGpu(double scale, CancellationToken ct)
    {
        if (!TryInitGpu() || _gpuAccel == null || _gpuKernel == null) return false;
        try
        {
            int total = Width * Height;
            using var dev = _gpuAccel.Allocate1D<RawPixel>(total);
            var p = new GpuParams
            {
                Width    = Width,
                Height   = Height,
                CenterX  = CenterX,
                CenterY  = CenterY,
                Scale    = scale,
                MaxIter  = MaxIterations,
                Bailout2 = Bailout2,
            };
            _gpuKernel(total, dev.View, p);
            _gpuAccel.Synchronize();
            if (ct.IsCancellationRequested) return false;
            var raw = new RawPixel[total];
            dev.CopyToCPU(raw);
            Parallel.For(0, total, new ParallelOptions { CancellationToken = ct }, i =>
            {
                if (ct.IsCancellationRequested) return;
                var rp = raw[i];
                ColorBuffer[i] = ColorFor(rp.Iter, rp.Zr, rp.Zi, rp.Dr, rp.Di, MaxIterations);
            });
            return true;
        }
        catch (Exception ex)
        {
            LastGpuError = ex.Message;
            return false;
        }
    }

    private static void Kernel(Index1D idx, ArrayView<RawPixel> output, GpuParams p)
    {
        int x = idx % p.Width;
        int y = idx / p.Width;
        if (y >= p.Height) return;
        double cr = p.CenterX + (x - p.Width  * 0.5) * p.Scale;
        double ci = p.CenterY + (y - p.Height * 0.5) * p.Scale;
        double zr = 0.0, zi = 0.0;
        double dr = 0.0, di = 0.0;
        int it = 0;
        int maxIt = p.MaxIter;
        for (; it < maxIt; it++)
        {
            double r2 = zr * zr + zi * zi;
            if (r2 >= p.Bailout2) break;
