{{SCALAR_Z_BODY}}
            zr = zr_new; zi = zi_new;
            dr = dr_new; di = di_new;
        }
        RawPixel rp;
        rp.Iter = it;
        rp.Zr = zr; rp.Zi = zi;
        rp.Dr = dr; rp.Di = di;
        output[idx] = rp;
    }

    public void Dispose()
    {
        _gpuAccel?.Dispose(); _gpuAccel = null;
        _gpuContext?.Dispose(); _gpuContext = null;
        _gpuKernel = null;
    }

